"use server";

import { z } from "zod";
import { refresh } from "next/cache";
import { db } from "@/lib/db";
import { getOrCreateCart, findCart, getCartItems, MAX_QTY } from "@/lib/cart";
import { track } from "@/lib/analytics";
import { rateLimit } from "@/lib/security";

const addSchema = z.object({
  productId: z.string().min(1).max(40),
  quantity: z.coerce.number().int().min(1).max(MAX_QTY).default(1),
  engravingText: z.string().trim().max(60).default(""),
});

export type CartResult = { ok: boolean; error?: string };

export async function addToCart(input: z.input<typeof addSchema>): Promise<CartResult> {
  if (!(await rateLimit("cart", 120, 60))) return { ok: false, error: "Too many requests" };
  const parsed = addSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid request" };
  const { productId, quantity, engravingText } = parsed.data;

  const product = await db.product.findFirst({ where: { id: productId, isActive: true }, select: { id: true, stock: true, price: true, engravingAvailable: true } });
  if (!product) return { ok: false, error: "This product is no longer available." };
  if (product.stock < 1) return { ok: false, error: "Sorry, this product is out of stock." };

  const cart = await getOrCreateCart();
  const text = product.engravingAvailable ? engravingText : "";
  const key = { cartId_productId_engravingText: { cartId: cart.id, productId, engravingText: text } };
  const existing = await db.cartItem.findUnique({ where: key });
  const nextQty = Math.min((existing?.quantity ?? 0) + quantity, MAX_QTY, product.stock);
  await db.cartItem.upsert({ where: key, create: { cartId: cart.id, productId, quantity: nextQty, engravingText: text }, update: { quantity: nextQty } });
  await db.cart.update({ where: { id: cart.id }, data: { updatedAt: new Date() } });
  await track("ADD_TO_CART", { productId, value: product.price * quantity });
  refresh();
  return { ok: true };
}

export async function updateCartItem(itemId: string, quantity: number): Promise<CartResult> {
  const cart = await findCart();
  if (!cart) return { ok: false, error: "Cart not found" };
  const item = await db.cartItem.findFirst({ where: { id: itemId, cartId: cart.id }, include: { product: { select: { stock: true } } } });
  if (!item) return { ok: false, error: "Item not found" };
  const q = Math.floor(Number(quantity));
  if (!Number.isFinite(q) || q < 1) await db.cartItem.delete({ where: { id: item.id } });
  else await db.cartItem.update({ where: { id: item.id }, data: { quantity: Math.min(q, MAX_QTY, item.product.stock) } });
  refresh();
  return { ok: true };
}

export async function removeCartItem(itemId: string): Promise<CartResult> {
  const cart = await findCart();
  if (!cart) return { ok: false };
  await db.cartItem.deleteMany({ where: { id: itemId, cartId: cart.id } });
  refresh();
  return { ok: true };
}

export type MiniCart = {
  items: { id: string; name: string; slug: string; image: string | null; price: number; quantity: number; engravingText: string }[];
  subtotal: number;
  count: number;
};

/** Lightweight cart snapshot for the slide-in cart drawer. */
export async function getMiniCart(): Promise<MiniCart> {
  const items = await getCartItems();
  const active = items.filter((i) => i.product.isActive);
  return {
    items: active.map((i) => ({
      id: i.id,
      name: i.product.name,
      slug: i.product.slug,
      image: i.product.images[0]?.url ?? null,
      price: i.product.price,
      quantity: i.quantity,
      engravingText: i.engravingText,
    })),
    subtotal: active.reduce((s, i) => s + i.product.price * i.quantity, 0),
    count: active.reduce((s, i) => s + i.quantity, 0),
  };
}
