import "server-only";
import { cookies } from "next/headers";
import { randomBytes } from "node:crypto";
import type { EventType, Prisma } from "@prisma/client";
import { db } from "./db";
import { getCurrentUser } from "./auth";

const VISITOR_COOKIE = "sm_vid";

/** Anonymous first-party visitor id (no IP / fingerprinting stored). Must run in an action or route handler. */
export async function visitorId() {
  const store = await cookies();
  let id = store.get(VISITOR_COOKIE)?.value;
  if (!id || !/^[a-f0-9]{24}$/.test(id)) {
    id = randomBytes(12).toString("hex");
    store.set(VISITOR_COOKIE, id, { httpOnly: true, sameSite: "lax", secure: process.env.NODE_ENV === "production", path: "/", maxAge: 60 * 60 * 24 * 365 });
  }
  return id;
}

export async function track(type: EventType, data: { path?: string; productId?: string; value?: number; meta?: Prisma.InputJsonValue } = {}) {
  try {
    const [vid, user] = await Promise.all([visitorId(), getCurrentUser()]);
    await db.analyticsEvent.create({ data: { type, visitorId: vid, userId: user?.id, ...data } });
  } catch (err) {
    console.error("analytics track failed", err);
  }
}
