"use server";

import { track } from "@/lib/analytics";

// Called from a client beacon so pages themselves stay cacheable.
export async function trackView(path: string, productId?: string) {
  const p = String(path).slice(0, 200);
  if (!p.startsWith("/") || p.startsWith("/admin")) return;
  await track(productId ? "PRODUCT_VIEW" : "PAGE_VIEW", { path: p, productId: productId?.slice(0, 40) });
}

export async function trackSearch(q: string) {
  const term = String(q).trim().toLowerCase().slice(0, 80);
  if (term) await track("SEARCH", { meta: { q: term } });
}
