"use server";

import { z } from "zod";
import { refresh } from "next/cache";
import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";

export type WishlistResult = { ok: true; saved: boolean } | { ok: false; needsLogin?: boolean; error?: string };

export async function toggleWishlist(productId: string): Promise<WishlistResult> {
  const user = await getCurrentUser();
  if (!user) return { ok: false, needsLogin: true };
  const id = z.string().min(1).max(40).safeParse(productId);
  if (!id.success) return { ok: false, error: "Invalid product" };
  const existing = await db.wishlistItem.findUnique({ where: { userId_productId: { userId: user.id, productId: id.data } } });
  if (existing) {
    await db.wishlistItem.delete({ where: { id: existing.id } });
    refresh();
    return { ok: true, saved: false };
  }
  if ((await db.wishlistItem.count({ where: { userId: user.id } })) >= 200) return { ok: false, error: "Wishlist is full" };
  const product = await db.product.findFirst({ where: { id: id.data, isActive: true }, select: { id: true } });
  if (!product) return { ok: false, error: "Product not found" };
  await db.wishlistItem.create({ data: { userId: user.id, productId: product.id } });
  refresh();
  return { ok: true, saved: true };
}

/** Product ids the current user has saved (used to render filled hearts on the client). */
export async function getWishlistIds(): Promise<string[]> {
  const user = await getCurrentUser();
  if (!user) return [];
  const rows = await db.wishlistItem.findMany({ where: { userId: user.id }, select: { productId: true } });
  return rows.map((r) => r.productId);
}
